-- Restore only server-accepted loot from the FINAL checkpoint of guarded finished runs.
-- Append-only compensation: do not rewrite wallet_ledger, Stars, XP, rankings or existing settlements.
-- One statement per line also supports the local D1 exec test harness.
CREATE TABLE IF NOT EXISTS run_reward_corrections (run_id TEXT PRIMARY KEY REFERENCES runs(id), previous_earned INTEGER NOT NULL, corrected_earned INTEGER NOT NULL, created_at INTEGER NOT NULL);
INSERT OR IGNORE INTO run_reward_corrections(run_id,previous_earned,corrected_earned,created_at) SELECT r.id,r.earned,CAST(json_extract(c.payload,'$.money') AS INTEGER),unixepoch()*1000 FROM runs r JOIN run_checkpoints c ON c.run_id=r.id AND c.seq=r.seq WHERE r.status='finished' AND r.verification_state='guarded' AND r.settlement_id IS NOT NULL AND json_valid(c.payload) AND json_type(c.payload,'$.money')='integer' AND json_extract(c.payload,'$.seq')=r.seq AND json_extract(c.payload,'$.seconds')=r.duration_seconds AND json_extract(c.payload,'$.kills')=r.kills AND json_extract(c.payload,'$.money')>r.earned AND json_extract(c.payload,'$.money')<=200000 AND json_extract(c.payload,'$.money')<=r.kills*25+CAST((r.duration_seconds/30.0+1)/5 AS INTEGER)*150 AND EXISTS(SELECT 1 FROM wallet_ledger l WHERE l.user_id=r.user_id AND l.reason='run' AND l.ref_id=r.id AND l.delta=r.earned);
INSERT INTO wallet_ledger(id,user_id,delta,reason,ref_id,created_at) SELECT 'run-loot-correction:'||a.run_id,r.user_id,a.corrected_earned-a.previous_earned,'run_correction',a.run_id,a.created_at FROM run_reward_corrections a JOIN runs r ON r.id=a.run_id WHERE NOT EXISTS(SELECT 1 FROM wallet_ledger l WHERE l.user_id=r.user_id AND l.reason='run_correction' AND l.ref_id=a.run_id);
UPDATE runs SET earned=(SELECT a.corrected_earned FROM run_reward_corrections a WHERE a.run_id=runs.id) WHERE id IN (SELECT run_id FROM run_reward_corrections);
